import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import "./CSS/Dashboard.css";

const Dashboard = () => {
  const navigate = useNavigate();
  const [users, setUsers] = useState([]);
  const [search, setSearch] = useState("");
  const [composeReceiver, setComposeReceiver] = useState("");
  const [composeMessage, setComposeMessage] = useState("");

  const currentUser = JSON.parse(localStorage.getItem("currentUser"));

  // Fetch all unique users except current user
  useEffect(() => {
    fetch("http://localhost:5000/get-users")
      .then((res) => res.json())
      .then((data) => {
        if (data.success) {
          const filtered = data.users.filter(
            (email) => email !== currentUser?.email
          );
          setUsers(filtered);
        } else {
          alert("Failed to load users");
        }
      })
      .catch(() => alert("Error fetching users"));
  }, [currentUser]);

  const handleLogout = () => {
    localStorage.removeItem("currentUser");
    navigate("/");
  };

  const handleOpenChat = (userEmail) => {
    navigate(`/messages/${encodeURIComponent(userEmail)}`);
  };

  const handleCompose = () => {
    if (!composeReceiver || !composeMessage) {
      alert("Both receiver and message are required.");
      return;
    }

    const payload = {
      sender: currentUser.email,
      receiver: composeReceiver.toLowerCase(),
      message: composeMessage
    };

    fetch("http://localhost:5000/send-message", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    })
      .then((res) => res.json())
      .then((data) => {
        if (data.success) {
          alert("Message sent successfully");
          setComposeReceiver("");
          setComposeMessage("");
        } else {
          alert("Failed to send message");
        }
      })
      .catch(() => alert("Network error during message send"));
  };

  const filteredUsers = users.filter((user) =>
    user.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="dashboard-container">
      <div className="dashboard-header">
        <input
          type="text"
          placeholder="Search Bar"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <button className="logout-button" onClick={handleLogout}>
          Logout
        </button>
      </div>

      <div className="dashboard-body">
        <div className="compose-card">
          <h3>Compose Message</h3>
          <input
            type="text"
            placeholder="Receiver Email"
            value={composeReceiver}
            onChange={(e) => setComposeReceiver(e.target.value)}
          />
          <textarea
            placeholder="Enter your message"
            value={composeMessage}
            onChange={(e) => setComposeMessage(e.target.value)}
          />
          <button onClick={handleCompose}>Send</button>
        </div>

        <h3 className="user-list-title">Recent Users</h3>
        {filteredUsers.length === 0 ? (
          <p className="center-text">No users to show</p>
        ) : (
          <ul className="user-list">
            {filteredUsers.map((user) => (
              <li
                key={user}
                className="user-item"
                onClick={() => handleOpenChat(user)}
              >
                {user}
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
